49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    /** Dedicated audit trail logger; carries a line for each successful owner create. */
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
103	     *  separated by '@', none of which contain whitespace or a second '@'. */
104	    private static final java.util.regex.Pattern EMAIL_PATTERN =
105	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
106	
107	    /** Disposable email domains that are not accepted as an owner's email. */
108	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
109	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
110	
111	    /**
112	     * Normalize the optional email: absent stays absent; when present it must be syntactically
113	     * valid and is lower-cased. Returns {@code false} if present but invalid, including when its
114	     * domain is on the disposable-domain blocklist.
115	     */
116	    private boolean normalizeEmail(Owner owner) {
117	        String email = owner.getEmail();
118	        if (email == null || email.isEmpty()) {
119	            owner.setEmail(null);
120	            return true;
121	        }
122	        if (!EMAIL_PATTERN.matcher(email).matches()) {
123	            return false;
124	        }
125	        email = email.toLowerCase(java.util.Locale.ROOT);
126	        String domain = email.substring(email.indexOf('@') + 1);
127	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
128	            return false;
129	        }
130	        owner.setEmail(email);
131	        return true;
132	    }
133	
134	    /**
135	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
136	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
137	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
138	     *
139	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
140	     *         a valid E.164 number.
141	     */
142	    private static String toE164(String raw) {
143	        if (raw == null) {
144	            return null;
145	        }
146	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
147	        String digits;
148	        if (cleaned.startsWith("+")) {
149	            digits = cleaned.substring(1);
150	        } else {
151	            if (cleaned.startsWith("0")) {
152	                cleaned = cleaned.substring(1);
153	            }
154	            digits = "61" + cleaned;
155	        }
156	        if (!digits.matches("\\d{8,15}")) {
157	            return null;
158	        }
159	        return "+" + digits;
160	    }
161	
162	    /**
163	     * Validate the national-number length of a canonical E.164 string against its country code:
164	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
165	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
166	     * string produced by {@link #toE164}.
167	     *
168	     * @return {@code true} when the national-number length is correct for the country code.
169	     */
170	    private static boolean hasValidNationalLength(String e164) {
171	        String digits = e164.substring(1);
172	        if (digits.startsWith("61")) {
173	            return digits.length() - 2 == 9;
174	        }
175	        if (digits.startsWith("1")) {
176	            return digits.length() - 1 == 10;
177	        }
178	        return true;
179	    }
180	
181	    /**
182	     * Build the customer code {@code <REGION>-<HASH8>}: REGION is the region code derived from the
183	     * owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN} when the postcode is absent or in no known
184	     * range) and HASH8 is the first 8 upper-case hex characters of SHA-256 over the concatenation of
185	     * the owner's normalized (E.164) telephone and last name (e.g. {@code NSW-3F9A0C17}). No sequence
186	     * numbers are used, so the base code is a pure function of the owner's region-and-hash identity.
187	     * When that base code collides with an existing owner's customerCode, {@code -<n>} is appended with
188	     * the smallest {@code n} of 2 or more that makes it unique, returning the de-duplicated code.
189	     */
190	    private String customerCodeFor(Owner owner) {
191	        String region = ownerMapper.regionFromPostcode(owner);
192	        if (region == null) {
193	            region = "UNKNOWN";
194	        }
195	        String base = region + "-" + hash8(owner.getTelephone(), owner.getLastName());
196	
197	        java.util.Set<String> existingCodes = new java.util.HashSet<>();
198	        for (Owner existing : this.clinicService.findAllOwners()) {
199	            String code = existing.getCustomerCode();
200	            if (code != null) {
201	                existingCodes.add(code);
202	            }
203	        }
204	        if (!existingCodes.contains(base)) {
205	            return base;
206	        }
207	        for (int n = 2; ; n++) {
208	            String candidate = base + "-" + n;
209	            if (!existingCodes.contains(candidate)) {
210	                return candidate;
211	            }
212	        }
213	    }
214	
215	    /**
216	     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
217	     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
218	     */
219	    private static String hash8(String normalizedTelephone, String lastName) {
220	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
221	            + (lastName == null ? "" : lastName);
222	        try {
223	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
224	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
225	            StringBuilder sb = new StringBuilder(8);
226	            for (int i = 0; i < 4; i++) {
227	                sb.append(String.format("%02X", digest[i]));
228	            }
229	            return sb.toString();
230	        }
231	        catch (java.security.NoSuchAlgorithmException e) {
232	            throw new IllegalStateException(e);
233	        }
234	    }
235	
236	    /** Common street-type abbreviations expanded during address normalization. */
237	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
238	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
239	
240	    /**
241	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
242	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
243	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
244	     */
245	    private static String normalizeAddress(String value) {
246	        if (value == null) {
247	            return "";
248	        }
249	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
250	        if (collapsed.isEmpty()) {
251	            return "";
252	        }
253	        String[] tokens = collapsed.split(" ");
254	        StringBuilder sb = new StringBuilder(collapsed.length());
255	        for (int i = 0; i < tokens.length; i++) {
256	            if (i > 0) {
257	                sb.append(' ');
258	            }
259	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
260	        }
261	        return sb.toString();
262	    }
263	
264	    /**
265	     * Resolve and normalize the owner's postal address, preferring the structured form.
266	     *
267	     * <p>When a non-blank {@code addressLine1} is supplied the structured form is used: it, and the
268	     * optional {@code addressLine2}, are normalized in place and the composed address is the
269	     * normalized addressLine1 with a single space and the normalized addressLine2 appended when
270	     * addressLine2 is present. Otherwise the flat {@code address} input is normalized. Returns
271	     * {@code null} when neither form yields a non-empty address, so the caller can reject the
272	     * request.
273	     */
274	    private String composeAddress(Owner owner) {
275	        String line1 = owner.getAddressLine1();
276	        if (line1 != null && !line1.isBlank()) {
277	            String normalizedLine1 = normalizeAddress(line1);
278	            owner.setAddressLine1(normalizedLine1);
279	            String line2 = owner.getAddressLine2();
280	            if (line2 != null && !line2.isBlank()) {
281	                String normalizedLine2 = normalizeAddress(line2);
282	                owner.setAddressLine2(normalizedLine2);
283	                return normalizedLine1 + " " + normalizedLine2;
284	            }
285	            owner.setAddressLine2(null);
286	            return normalizedLine1.isEmpty() ? null : normalizedLine1;
287	        }
288	        String normalized = normalizeAddress(owner.getAddress());
289	        return normalized.isEmpty() ? null : normalized;
290	    }
291	
292	    /**
293	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
294	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
295	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
296	     */
297	    private static String normalizeForHousehold(String value) {
298	        if (value == null) {
299	            return "";
300	        }
301	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
302	    }
303	
304	    /**
305	     * Return the owners that already share this owner's household, i.e. resolve to the same
306	     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
307	     * postcode).
308	     */
309	    private List<Owner> householdMembers(Owner owner) {
310	        String householdId = householdIdFor(owner);
311	        List<Owner> members = new java.util.ArrayList<>();
312	        for (Owner existing : this.clinicService.findAllOwners()) {
313	            if (existing.isDeleted()) {
314	                continue;
315	            }
316	            if (householdId.equals(householdIdFor(existing))) {
317	                members.add(existing);
318	            }
319	        }
320	        return members;
321	    }
322	
323	    /**
324	     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
325	     * the same deterministic {@link #householdIdFor(Owner) householdId}.
326	     */
327	    private boolean sharesHouseholdWithExisting(Owner owner) {
328	        return !householdMembers(owner).isEmpty();
329	    }
330	
331	    /**
332	     * Count the existing owners that share this owner's first name and last name, compared
333	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
334	     */
335	    private int namesakeCount(Owner owner) {
336	        String firstName = owner.getFirstName();
337	        String lastName = owner.getLastName();
338	        int count = 0;
339	        for (Owner existing : this.clinicService.findAllOwners()) {
340	            if (firstName != null && lastName != null
341	                && firstName.equalsIgnoreCase(existing.getFirstName())
342	                && lastName.equalsIgnoreCase(existing.getLastName())) {
343	                count++;
344	            }
345	        }
346	        return count;
347	    }
348	
349	    /**
350	     * A stable, shared household identifier: the first 12 hex characters of SHA-256 over
351	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes an empty string).
352	     * Because it is a pure function of the last name and postcode, every owner in the same household
353	     * deterministically resolves to the same value.
354	     */
355	    private static String householdIdFor(Owner owner) {
356	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
357	        String key = normalizeForHousehold(owner.getLastName()) + "|" + postcode;
358	        try {
359	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
360	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
361	            StringBuilder sb = new StringBuilder(12);
362	            for (int i = 0; i < 6; i++) {
363	                sb.append(String.format("%02X", digest[i]));
364	            }
365	            return sb.toString();
366	        }
367	        catch (java.security.NoSuchAlgorithmException e) {
368	            throw new IllegalStateException(e);
369	        }
370	    }
371	
372	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
373	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
374	        "NSW", new int[] {2000, 2099},
375	        "VIC", new int[] {3000, 3099},
376	        "QLD", new int[] {4000, 4099});
377	
378	    /**
379	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
380	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
381	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
382	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
383	     * postcode.
384	     */
385	    private boolean isPostcodeValid(Owner owner) {
386	        String postcode = owner.getPostcode();
387	        if (postcode == null || postcode.isEmpty()) {
388	            return true;
389	        }
390	        if (!postcode.matches("\\d{4}")) {
391	            return false;
392	        }
393	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
394	        if (range == null) {
395	            return true;
396	        }
397	        int value = Integer.parseInt(postcode);
398	        return value >= range[0] && value <= range[1];
399	    }
400	
401	    /**
402	     * Find an existing owner that makes this (already known to be non-hard-duplicate) owner a
403	     * "possible duplicate": one that shares the owner's last name (case-insensitive) and postcode
404	     * but carries a different (normalized) telephone. When several match, the one with the smallest
405	     * id is chosen so the result is deterministic. Returns {@code null} when the owner has no
406	     * postcode or no such existing owner exists.
407	     */
408	    private Owner possibleDuplicateOf(Owner owner) {
409	        String lastName = owner.getLastName();
410	        String postcode = owner.getPostcode();
411	        String telephone = owner.getTelephone();
412	        if (lastName == null || postcode == null || postcode.isEmpty()) {
413	            return null;
414	        }
415	        Owner match = null;
416	        for (Owner existing : this.clinicService.findAllOwners()) {
417	            if (lastName.equalsIgnoreCase(existing.getLastName())
418	                && postcode.equals(existing.getPostcode())
419	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
420	                if (match == null || (existing.getId() != null && match.getId() != null
421	                    && existing.getId() < match.getId())) {
422	                    match = existing;
423	                }
424	            }
425	        }
426	        return match;
427	    }
428	
429	    /** Maximum number of owners permitted in a single city. */
430	    private static final int CITY_CAPACITY = 50;
431	
432	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
433	    private static final int DAILY_CREATE_LIMIT = 100;
434	
435	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
436	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
437	
438	    /**
439	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
440	     * Used to enforce the per-city capacity on create (before this owner is saved).
441	     */
442	    private int cityOwnerCount(Owner owner) {
443	        String city = owner.getCity();
444	        int count = 0;
445	        for (Owner existing : this.clinicService.findAllOwners()) {
446	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
447	                count++;
448	            }
449	        }
450	        return count;
451	    }
452	
453	    /** Fixed public holidays the business-day roll skips. */
454	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
455	        java.time.LocalDate.parse("2026-01-01"),
456	        java.time.LocalDate.parse("2026-01-26"),
457	        java.time.LocalDate.parse("2026-04-25"),
458	        java.time.LocalDate.parse("2026-12-25"),
459	        java.time.LocalDate.parse("2026-12-28"));
460	
461	    /**
462	     * Roll a registration date forward onto a business day: any Saturday, Sunday or listed public
463	     * holiday is advanced one day at a time until a non-holiday weekday is reached; a date that is
464	     * already a non-holiday weekday is returned unchanged. Applied to the effective registration date
465	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
466	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
467	     */
468	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
469	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
470	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
471	            || PUBLIC_HOLIDAYS.contains(date)) {
472	            date = date.plusDays(1);
473	        }
474	        return date;
475	    }
476	
477	    /**
478	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
479	     * per-day create limit on create (before this owner is saved).
480	     */
481	    private int ownersRegisteredOn(java.time.LocalDate day) {
482	        int count = 0;
483	        for (Owner existing : this.clinicService.findAllOwners()) {
484	            if (day.equals(existing.getRegistrationDate())) {
485	                count++;
486	            }
487	        }
488	        return count;
489	    }
490	
491	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
492	    @Override
493	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
494	        HttpHeaders headers = new HttpHeaders();
495	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
496	        if (!isPostcodeValid(owner)) {
497	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
498	        }
499	        String telephone = toE164(owner.getTelephone());
500	        if (telephone == null || !hasValidNationalLength(telephone)) {
501	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
502	        }
503	        if (!normalizeEmail(owner)) {
504	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
505	        }
506	        String address = composeAddress(owner);
507	        if (address == null) {
508	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
509	        }
510	        owner.setAddress(address);
511	        owner.setTelephone(telephone);
512	        if (owner.getRegistrationDate() != null
513	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
514	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
515	        }
516	        java.time.LocalDate registrationDate = toBusinessDay(
517	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
518	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
519	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
520	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
521	        }
522	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
523	            return new ResponseEntity<>(HttpStatus.CONFLICT);
524	        }
525	        // The householdId is deterministic (SHA-256 over normalized lastName + '|' + postcode), so
526	        // owners with the same last name and postcode automatically share it. The link is no longer
527	        // created by copying an existing owner's id around.
528	        owner.setHouseholdId(householdIdFor(owner));
529	        List<Owner> householdMembers = householdMembers(owner);
530	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
531	        boolean declaredHouseholdMember = sharesHousehold && !householdMembers.isEmpty();
532	
533	        // Hard duplicate: a new owner whose WHOLE identityKey (telephone|email|householdId) equals an
534	        // existing owner's is a byte-for-byte identity match and is always rejected.
535	        String identityKey = owner.getIdentityKey();
536	        for (Owner existing : this.clinicService.findAllOwners()) {
537	            if (existing.isDeleted()) {
538	                continue;
539	            }
540	            if (identityKey.equals(existing.getIdentityKey())) {
541	                return new ResponseEntity<>(HttpStatus.CONFLICT);
542	            }
543	        }
544	        // Household duplicate: another owner already shares this (last name, postcode) household.
545	        // Rejected as a duplicate unless the caller sets 'sharesHousehold', which now only bypasses
546	        // this block (the shared householdId itself is already assigned deterministically above).
547	        if (!householdMembers.isEmpty() && !sharesHousehold) {
548	            return new ResponseEntity<>(HttpStatus.CONFLICT);
549	        }
550	        // A declared household member is not a suspected duplicate. Otherwise, flag an owner that
551	        // shares an existing owner's last name and postcode with a different telephone.
552	        if (declaredHouseholdMember) {
553	            owner.setPossibleDuplicate(false);
554	            owner.setPossibleDuplicateOf(null);
555	        }
556	        else {
557	            Owner duplicateOf = possibleDuplicateOf(owner);
558	            owner.setPossibleDuplicate(duplicateOf != null);
559	            owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
560	        }
561	        owner.setNamesakeCount(namesakeCount(owner));
562	        owner.setHouseholdSize(householdMembers.size() + 1);
563	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
564	        owner.setRegistrationDate(registrationDate);
565	        owner.setCustomerCode(customerCodeFor(owner));
566	        this.clinicService.saveOwner(owner);
567	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
568	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
569	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
570	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
571	        headers.setLocation(UriComponentsBuilder.newInstance()
572	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
573	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
574	    }
575	
576	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
577	    @Override
578	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
579	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
580	        if (currentOwner == null) {
581	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
582	        }
583	        currentOwner.setAddress(ownerFieldsDto.getAddress());
584	        currentOwner.setCity(ownerFieldsDto.getCity());
585	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
586	        currentOwner.setLastName(ownerFieldsDto.getLastName());
587	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
588	        currentOwner.setEmail(ownerFieldsDto.getEmail());
589	        if (!normalizeEmail(currentOwner)) {
590	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
591	        }
592	        this.clinicService.saveOwner(currentOwner);
593	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
594	    }
595	
596	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
597	    @Transactional
598	    @Override
599	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
600	        Owner owner = this.clinicService.findOwnerById(ownerId);
601	        if (owner == null) {
602	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
603	        }
604	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
605	        owner.setDeleted(true);
606	        this.clinicService.saveOwner(owner);
607	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
608	    }
609	
610	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
611	    @Override
612	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
613	        Owner owner = this.clinicService.findOwnerById(ownerId);
614	        if (owner == null) {
615	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
616	        }
617	        HttpHeaders headers = new HttpHeaders();
618	        Pet pet = petMapper.toPet(petFieldsDto);
619	        owner.setId(ownerId);
620	        pet.setOwner(owner);
621	        pet.getType().setName(null);
622	        this.clinicService.savePet(pet);
623	        PetDto petDto = petMapper.toPetDto(pet);
624	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
625	            .buildAndExpand(pet.getId()).toUri());
626	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
627	    }
628	
629	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
630	    @Override
631	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
632	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
633	        if (currentOwner != null) {
634	            Pet currentPet = this.clinicService.findPetById(petId);
635	            if (currentPet != null) {
636	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
637	                currentPet.setName(petFieldsDto.getName());
638	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
639	                this.clinicService.savePet(currentPet);
640	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
641	            }
642	        }
643	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
644	    }
