661	
662	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
663	    @Override
664	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
665	        Owner owner = this.clinicService.findOwnerById(ownerId);
